INSERT INTO `compliance_requirements` VALUES (1,'FAC-TDA','Technology Demonstration Area in place','A working demonstration area of at least 1,000 sq.m. — no minimum for urban and peri-urban gardens, 1 hectare for coconut-based farms under the CFIDP, 25 heads for livestock.','Qualification Requirements — The Farm, item 3(a)','facilities','farming','ongoing',1,10,'2026-08-20 14:14:58'),(2,'FAC-HOLDING','Holding area available','A holding area able to take a visiting group for orientation and hands-on sessions.','Qualification Requirements — The Farm, item 3(b)','facilities','all','ongoing',1,20,'2026-08-20 14:14:58'),(3,'FAC-WASH','Wash area available','A wash area for tools, equipment and produce.','Qualification Requirements — The Farm, item 3(c)','facilities','all','ongoing',1,30,'2026-08-20 14:14:58'),(4,'FAC-TOILET','Toilet facilities available','Toilet facilities for visitors and training participants.','Qualification Requirements — The Farm, item 3(d)','facilities','all','ongoing',1,40,'2026-08-20 14:14:58'),(5,'FAC-ACCESS','Accessible by land transport','The site is reachable by land and other transportation facilities.','Qualification Requirements — The Farm, item 4','facilities','all','ongoing',1,50,'2026-08-20 14:14:58'),(6,'OPS-FARMING-SYSTEM','Diversified or specialised farming system implemented','The farm runs a diversified and integrated farming system, a specialised system, or demonstrates agriculture and fisheries technologies.','Responsibilities of LSA Operator — farming LSA','operations','farming','ongoing',1,60,'2026-08-20 14:14:58'),(7,'OPS-PROCESSING-VALUE-CHAIN','Agri-processing promoted through the value chain','The enterprise implements and promotes agri-processing activities across the value chain.','Responsibilities of LSA Operator — agri-processing enterprise','operations','agri_processing','ongoing',1,70,'2026-08-20 14:14:58'),(8,'OPS-DEMO-AREA','Site made available as a demonstration area','The farm or enterprise is open as a demonstration area for hands-on learning.','Responsibilities of LSA Operator','operations','all','ongoing',1,80,'2026-08-20 14:14:58'),(9,'OPS-LECTURES','Lectures and orientations provided','Lectures and orientations are given to on-site training participants, visiting groups, ATI scholarship grantees, 4-H youth trainees and other groups arranged by the ATI.','Responsibilities of LSA Operator','operations','all','ongoing',1,90,'2026-08-20 14:14:58'),(10,'OPS-SHARE-TECH','Technologies shared with fellow farmers','Technologies applied on the site are shared with fellow farmers and agri-processors.','Responsibilities of LSA Operator','operations','all','ongoing',1,100,'2026-08-20 14:14:58'),(11,'REC-OPERATION-RECORDS','Operation records maintained','Records of production and sales data, technologies developed or shared, activities undertaken, and visitors and trainees served are kept up to date.','Responsibilities of LSA Operator','records_reporting','all','ongoing',1,110,'2026-08-20 14:14:58'),(12,'REC-SEMESTRAL-REPORT','Semestral accomplishment report submitted','A semestral accomplishment report containing the maintained operation records is submitted to the ATI.','Responsibilities of LSA Operator','records_reporting','all','semestral',1,120,'2026-08-20 14:14:58'),(13,'REC-MONITORING-ACCESS','ATI field monitoring allowed','ATI personnel are able to conduct field monitoring and visits, and are given honest answers to questions raised.','Responsibilities of LSA Operator','records_reporting','all','ongoing',1,130,'2026-08-20 14:14:58'),(14,'REC-FIVE-YEAR','Operation sustained for five years','The operator sustains operation as an LSA for five (5) years.','Responsibilities of LSA Operator','records_reporting','all','five_year',1,140,'2026-08-20 14:14:58'),(15,'CAP-ATTEND-TRAINING','ATI monitoring and capability-building activities attended','The operator attends the monitoring and capability-building interventions the ATI requires.','Responsibilities of LSA Operator','capability','all','annual',1,150,'2026-08-20 14:14:58'),(16,'CAP-RSBSA','RSBSA / NCFRS registration current','The farmer is registered in the RSBSA maintained by the DA; coconut-based farmers are registered in the NCFRS maintained by the PCA.','Qualification Requirements — The Farmer/Farm Family, item 8','capability','farming','annual',1,160,'2026-08-20 14:14:58'),(17,'ASSIST-DEV-PLAN','Development plan implemented as approved','Where fund support was given: the development plan is implemented as approved and completed within the agreed timeframe, with the operator providing a counterpart.','Responsibilities of LSA Operator — with fund support','assistance','all','once',1,170,'2026-08-20 14:14:58'),(18,'ASSIST-COMPLETION-REPORT','LSA Project Completion Report submitted','Where fund support was given: the ATI is notified on completion of the development plan through an LSA Project Completion Report, submitted quarterly as required by the COA.','Provision of Assistance / Responsibilities of LSA Operator','assistance','all','once',1,180,'2026-08-20 14:14:58');
/*!40000 ALTER TABLE `compliance_requirements` ENABLE KEYS */;
UNLOCK TABLES;

