INSERT INTO `services` VALUES (43,'training','Training of Trainers','Prepares LSA cooperators to deliver farmer-level training on behalf of the Institute.','ATI-RTC V (Bicol)','LSA cooperators and farmer-leaders','Accredited LSA I and LSA II operators','',NULL,NULL,NULL,NULL,'open',NULL,NULL,'2026-09-02 00:38:20','2026-09-02 00:38:20'),(44,'training','Farm Entrepreneurship and Farm Business Planning','Running the farm as a business: costing, markets and a written business plan.','ATI-RTC V (Bicol)','LSA operators and farm families','Accredited LSA operators','',NULL,NULL,NULL,NULL,'open',NULL,NULL,'2026-09-02 00:38:20','2026-09-02 00:38:20'),(45,'training','Farm Planning and Development','Laying out and developing the farm, including the technology demonstration area.','ATI-RTC V (Bicol)','LSA operators','Accredited LSA operators','',NULL,NULL,NULL,NULL,'open',NULL,NULL,'2026-09-02 00:38:20','2026-09-02 00:38:20'),(46,'training','Financial Literacy including Farm Record Keeping','Managing farm finances and keeping the production and sales records an LSA is required to maintain.','ATI-RTC V (Bicol)','LSA operators and farm families','Accredited LSA operators','',NULL,NULL,NULL,NULL,'open',NULL,NULL,'2026-09-02 00:38:20','2026-09-02 00:38:20'),(47,'training','Good Agriculture Practices, HALAL and Food Safety','GAP, HALAL and food safety standards for farm and agri-processing operations.','ATI-RTC V (Bicol)','LSA operators, agri-processing enterprises','Accredited LSA operators','',NULL,NULL,NULL,NULL,'open',NULL,NULL,'2026-09-02 00:38:20','2026-09-02 00:38:20'),(48,'training','Climate Resilient Agriculture','Practices that keep the farm productive through drought, flooding and typhoons.','ATI-RTC V (Bicol)','LSA operators and Agricultural Extension Workers','Accredited LSA operators','',NULL,NULL,NULL,NULL,'open',NULL,NULL,'2026-09-02 00:38:20','2026-09-02 00:38:20'),(49,'training','New and Emerging Technologies in Agriculture and Fishery','Technologies newly released for extension in agriculture and fishery.','ATI-RTC V (Bicol)','LSA operators, AEWs','Accredited LSA operators','',NULL,NULL,NULL,NULL,'open',NULL,NULL,'2026-09-02 00:38:20','2026-09-02 00:38:20'),(50,'training','Values Formation','Values formation for farmer-leaders and cooperators.','ATI-RTC V (Bicol)','LSA operators and farmer-leaders','Accredited LSA operators','',NULL,NULL,NULL,NULL,'open',NULL,NULL,'2026-09-02 00:38:20','2026-09-02 00:38:20'),(51,'training','Digital Agriculture','Digital tools and internet-based information resources for farm operations.','ATI-RTC V (Bicol)','LSA operators, AEWs, 4-H youth','Accredited LSA operators','',NULL,NULL,NULL,NULL,'open',NULL,NULL,'2026-09-02 00:38:20','2026-09-02 00:38:20'),(52,'demonstration','Technology Demonstration Hosting','The farm serves as a demonstration area for hands-on learning by training participants, visiting groups, ATI scholarship grantees and 4-H youth trainees.','ATI-RTC V (Bicol)','Training participants, visiting groups, students','Accredited LSA with a technology demonstration area','',NULL,NULL,NULL,NULL,'open',NULL,NULL,'2026-09-02 00:38:20','2026-09-02 00:38:20'),(53,'information_support','IEC Materials and Information Support','Information, education and communication materials and internet-based information resources provided to the farm’s clientele.','ATI-RTC V (Bicol)','Farmers and fisherfolk in the service area','Open to all LSA clientele','',NULL,NULL,NULL,NULL,'open',NULL,NULL,'2026-09-02 00:38:20','2026-09-02 00:38:20'),(54,'technical_assistance','On-site Technical Assistance and Farm Advisory','Farm business advisory and technical guidance provided to cooperators, including monitoring visits by ATI personnel.','ATI-RTC V (Bicol)','LSA operators','Accredited LSA operators','',NULL,NULL,NULL,NULL,'open',NULL,NULL,'2026-09-02 00:38:20','2026-09-02 00:38:20'),(55,'complementary_project','PAF-ESP Accreditation Support','Support for certified LSAs organising into associations or networks and applying for accreditation as Private Agriculture and Fisheries – Extension Service Providers. Promising proposals may receive financial grants, subject to available ATI funding.','ATI-RTC V (Bicol)','LSA II operators, LSA networks and associations','Priority to LSA II','',NULL,NULL,NULL,NULL,'open',NULL,NULL,'2026-09-02 00:38:20','2026-09-02 00:38:20'),(56,'complementary_project','FITS Kiosk (Satellite FITS Center)','The farm becomes a Farmers’ Information and Technology Services kiosk, serving as a satellite FITS Center providing IEC materials and internet-based information resources.','ATI-RTC V (Bicol)','LSA II operators and their clientele','Priority to LSA II','',NULL,NULL,NULL,NULL,'open',NULL,NULL,'2026-09-02 00:38:20','2026-09-02 00:38:20'),(57,'complementary_project','Artificial Insemination (AI) sa Barangay','Recipient of the AI sa Barangay Project under the National Livestock Program.','ATI-RTC V (Bicol)','LSA II operators engaged in livestock','Priority to LSA II, livestock operations','TBA',475,'2026-09-09','2026-09-30',1000,'open',NULL,NULL,'2026-09-02 00:38:20','2026-09-04 05:40:11');
